        internal sealed class Choice
        {
            internal string Id = "", Chinese = "";
            internal Rect TextBounds = Rect.Empty, ControlBounds = Rect.Empty;
        }
        internal sealed class ChoiceControl
        {
            internal string Id = "";
            internal Rect Bounds = Rect.Empty;
