        }

        public void UpdateSettings(List<NavigationDisplayRow> rows, string status)
        {
            bool entering = !settingsMode;
            settingsAligned = false;
            settingsMode = true; Title = "语桥 · 设置中文"; caption.Text = "设置中文";
