using System;
using System.Text;
using System.Text.RegularExpressions;

namespace Yuqiao
{
    /// <summary>
    /// Target-language typography only. No translation, network, files or UI.
    /// Markdown code, obvious standalone code, URLs, addresses and numeric
    /// punctuation are copied verbatim. Ambiguous ASCII commas are left alone.
    /// </summary>
    public static class TranslationPunctuation
    {
        private static readonly Regex ProtectedToken = new Regex(
            @"\G(?:(?:https?://|ftp://|www\.)[^\s<>""'`，。、！？：；（）「」『』“”‘’]+" +
            @"|[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}" +
            @"|\b(?:[A-Za-z]\.){2,}" +
            @"|\b(?:Mr|Mrs|Ms|Dr|Prof|Sr|Jr|St|vs|etc)\." +
            @"|\d+(?:[.,:]\d+)+" +
            @"|!==?|===?|<=|>=|=>|&&|\|\|)",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(200));

        private static readonly Regex CodeLine = new Regex(
            @"^(?:(?://|/\*|\*/|#include\b|<!|</?[A-Za-z][^>]*>)" +
            @"|(?:using|import|package|namespace|public|private|protected|class|def|function|const|let|var|return|throw)\s" +
            @"|(?:if|for|while|switch|catch)\s*\(" +
            @"|[A-Za-z_$][\w.$\[\]]*\s*(?:=(?!=)|\+=|-=|:=)" +
            @"|[A-Za-z_$][\w.$]*\s*\(.*\)\s*;?\s*$" +
            @"|[""'][^""']+[""']\s*:" +
            @"|[{}\[\]]\s*[,;]?\s*$)",
            RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(200));

        public static string Normalize(string text, string target)
        {
            if (String.IsNullOrEmpty(text)) return text;
            bool japanese = String.Equals(target, "ja", StringComparison.OrdinalIgnoreCase);
            bool english = String.Equals(target, "en", StringComparison.OrdinalIgnoreCase);
            if (!japanese && !english) return text;

            StringBuilder result = new StringBuilder(text.Length + 16);
            for (int i = 0; i < text.Length; )
            {
                int end;
                if (TryCodeSpan(text, i, out end) || TryCodeLine(text, i, out end))
                { result.Append(text, i, end - i); i = end; continue; }
                Match protectedMatch = ProtectedToken.Match(text, i);
                if (protectedMatch.Success && protectedMatch.Index == i)
                { result.Append(protectedMatch.Value); i += protectedMatch.Length; continue; }

                char current = text[i];
                if (japanese) result.Append(JapaneseCharacter(text, i));
                else
                {
                    char converted = EnglishCharacter(current);
                    if (converted != current)
                    {
                        if (IsClosingPunctuation(converted)) TrimTrailingSpaces(result);
                        if (IsOpeningBracket(converted) && NeedsSpaceBeforeOpening(result)) result.Append(' ');
                        result.Append(converted);
                        if (NeedsEnglishSpaceAfter(text, i, converted)) result.Append(' ');
                    }
                    else result.Append(current);
                }
                i++;
            }
            return result.ToString();
        }

        private static char JapaneseCharacter(string text, int index)
        {
            switch (text[index])
            {
                case '，': return '、';
                case '?': return '？';
                case '!': return '！';
                case ':': return '：';
                case ';': return '；';
                case '“': return '「';
                case '”': return '」';
                case '‘': return '『';
                case '’': return '』';
                case '.': return IsSentencePeriod(text, index) ? '。' : '.';
                default: return text[index];
            }
        }

        private static bool IsSentencePeriod(string text, int index)
        {
            if (index > 0 && text[index - 1] == '.') return false;
            if (index + 1 < text.Length && text[index + 1] == '.') return false;
            if (index + 1 == text.Length) return true;
            char next = text[index + 1];
            return Char.IsWhiteSpace(next) || ")]\"'”’」』）］!?！？".IndexOf(next) >= 0
                || (next >= '\u3040' && next <= '\u30ff') || (next >= '\u3400' && next <= '\u9fff');
        }

        private static char EnglishCharacter(char value)
        {
            switch (value)
            {
                case '，': case '、': return ',';
                case '。': case '．': return '.';
                case '？': return '?';
                case '！': return '!';
                case '：': return ':';
                case '；': return ';';
                case '（': return '(';
                case '）': return ')';
                case '［': case '【': return '[';
                case '］': case '】': return ']';
                case '｛': return '{';
                case '｝': return '}';
                case '“': case '”': case '「': case '」': return '"';
                case '‘': case '’': case '『': case '』': return '\'';
                default: return value;
            }
        }

        private static bool NeedsEnglishSpaceAfter(string text, int index, char converted)
        {
            if (index + 1 >= text.Length) return false;
            char next = text[index + 1];
            if (Char.IsWhiteSpace(next)) return false;
            if (",.;:!?，。．、；：！？)]}）］｝】\"'”’」』".IndexOf(next) >= 0) return false;
            if (index > 0 && Char.IsDigit(text[index - 1]) && Char.IsDigit(next)
                && (converted == ',' || converted == '.' || converted == ':')) return false;
            // Curly apostrophes inside English words are not closing quotations.
            if (converted == '\'' && index > 0 && Char.IsLetter(text[index - 1]) && Char.IsLetter(next)) return false;
            bool originalClosingQuote = "”’」』".IndexOf(text[index]) >= 0;
            return ",.;:!?)]}".IndexOf(converted) >= 0 || originalClosingQuote;
        }

        private static bool IsClosingPunctuation(char value) { return ",.;:!?)]}".IndexOf(value) >= 0; }
        private static bool IsOpeningBracket(char value) { return "([{".IndexOf(value) >= 0; }
        private static bool NeedsSpaceBeforeOpening(StringBuilder result)
        {
            if (result.Length == 0) return false;
            char previous = result[result.Length - 1];
            return Char.IsLetterOrDigit(previous) || ")]}\"'".IndexOf(previous) >= 0;
        }
        private static void TrimTrailingSpaces(StringBuilder result)
        {
            while (result.Length > 0 && (result[result.Length - 1] == ' ' || result[result.Length - 1] == '\t')) result.Length--;
        }

        private static bool TryCodeLine(string text, int index, out int end)
        {
            end = index;
            if (index != 0 && text[index - 1] != '\n') return false;
            int lineEnd = text.IndexOf('\n', index);
            if (lineEnd < 0) lineEnd = text.Length;
            string line = text.Substring(index, lineEnd - index).TrimStart(' ', '\t');
            if (!CodeLine.IsMatch(line)) return false;
            end = lineEnd < text.Length ? lineEnd + 1 : lineEnd;
            return true;
        }

        private static bool TryCodeSpan(string text, int index, out int end)
        {
            end = index;
            char marker = text[index];
            if (marker != '`' && marker != '~') return false;
            int count = 1;
            while (index + count < text.Length && text[index + count] == marker) count++;
            bool lineStart = true;
            for (int before = index - 1; before >= 0 && text[before] != '\n'; before--)
                if (text[before] != ' ' && text[before] != '\t') { lineStart = false; break; }
            bool fence = count >= 3 && lineStart;
            if (marker == '~' && !fence) return false;
            string delimiter = new string(marker, count);
            int search = index + count;
            while (search < text.Length)
            {
                int closing = text.IndexOf(delimiter, search, StringComparison.Ordinal);
                if (closing < 0) break;
                int closingCount = count;
                while (closing + closingCount < text.Length && text[closing + closingCount] == marker) closingCount++;
                if (!fence)
                {
                    if (closingCount == count) { end = closing + count; return true; }
                }
                else
                {
                    bool closingAtStart = true;
                    for (int before = closing - 1; before >= 0 && text[before] != '\n'; before--)
                        if (text[before] != ' ' && text[before] != '\t') { closingAtStart = false; break; }
                    if (closingAtStart) { end = closing + closingCount; return true; }
                }
                search = closing + closingCount;
            }
            // Preserve unfinished code rather than guessing where prose resumes.
            end = text.Length;
            return true;
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;

namespace Yuqiao
{
    public sealed class TranslationResult
    {
        public string Text;
        public string Provider;
        public long ElapsedMs;
    }

    /// <summary>
    /// Conventional machine translation only. No large-model service or API key.
    /// The Edge endpoint was observed in KISS Translator's microsoft.js adapter;
    /// this is an original implementation and includes none of that project's code.
    /// https://github.com/fishjar/kiss-translator/blob/dev/src/builtin-plugins/microsoft.js
    /// Public client endpoints may change and have no promised free service level.
    /// </summary>
    public sealed class TranslationService : IDisposable
    {
        private const int CacheCapacity = 200;
        private const int RequestTimeoutSeconds = 8;
        private readonly HttpClient client;
        private readonly object cacheLock = new object();
        private readonly Dictionary<string, CacheItem> cache = new Dictionary<string, CacheItem>();
        private readonly Queue<string> cacheOrder = new Queue<string>();
        private bool disposed;

        private sealed class CacheItem
        {
            public string Text;
            public string Provider;
        }

        public TranslationService() : this(new HttpClientHandler())
        {
        }

        // Internal seam for deterministic network-failure checks; normal UI uses the default constructor.
        internal TranslationService(HttpMessageHandler handler)
        {
            // .NET Framework otherwise follows older OS TLS defaults on some PCs.
            ServicePointManager.SecurityProtocol |= SecurityProtocolType.Tls12;
            client = new HttpClient(handler);
            client.Timeout = Timeout.InfiniteTimeSpan;
            client.DefaultRequestHeaders.UserAgent.ParseAdd("Yuqiao/1.0");
        }

        public async Task<TranslationResult> TranslateAsync(string text, string source, string target, CancellationToken token)
        {
            token.ThrowIfCancellationRequested();
            if (disposed) throw new ObjectDisposedException("TranslationService");
            if (String.IsNullOrWhiteSpace(text)) throw new ArgumentException("请先输入需要翻译的文字。");
            if (text.Length > 5000) throw new ArgumentException("每次最多翻译 5000 个字符，请分段输入。");
            ValidateLanguage(source, true);
            ValidateLanguage(target, false);

            if (source == target)
                return new TranslationResult { Text = text, Provider = "原文", ElapsedMs = 0 };

            // Length prefixes prevent key collisions even when text includes separators.
            string key = source.Length + ":" + source + target.Length + ":" + target + text.Length + ":" + text;
            lock (cacheLock)
            {
                CacheItem hit;
                if (cache.TryGetValue(key, out hit))
                    return new TranslationResult { Text = hit.Text, Provider = hit.Provider + " · 缓存", ElapsedMs = 0 };
            }

            Stopwatch timer = Stopwatch.StartNew();
            string translated = null;
            string provider = "Microsoft";
            bool useFallback = false;
            try
            {
                translated = await TranslateMicrosoftAsync(text, source, target, token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                token.ThrowIfCancellationRequested();
                useFallback = true;
            }
            catch (HttpRequestException)
            {
                token.ThrowIfCancellationRequested();
                useFallback = true;
            }
            catch (InvalidOperationException)
            {
                token.ThrowIfCancellationRequested();
                useFallback = true;
            }
            if (useFallback)
            {
                translated = await TranslateFallbackAsync(text, source, target, token).ConfigureAwait(false);
                provider = "Google（备用）";
            }

            token.ThrowIfCancellationRequested();
            timer.Stop();
            translated = TranslationPunctuation.Normalize(translated, target);
            lock (cacheLock)
            {
                if (!cache.ContainsKey(key))
                {
                    while (cache.Count >= CacheCapacity)
                        cache.Remove(cacheOrder.Dequeue());
                    cache.Add(key, new CacheItem { Text = translated, Provider = provider });
                    cacheOrder.Enqueue(key);
                }
            }
            return new TranslationResult { Text = translated, Provider = provider, ElapsedMs = timer.ElapsedMilliseconds };
        }

        /// <summary>
        /// Explicit second Japanese candidate: Google only, independent of the primary chain.
        /// Call only when the user requests an alternative to avoid unnecessary provider traffic.
        /// </summary>
        public async Task<TranslationResult> TranslateAlternativeJapaneseAsync(string text, CancellationToken token)
        {
            token.ThrowIfCancellationRequested();
            if (disposed) throw new ObjectDisposedException("TranslationService");
            if (String.IsNullOrWhiteSpace(text)) throw new ArgumentException("请先输入需要翻译的文字。");
            if (text.Length > 5000) throw new ArgumentException("每次最多翻译 5000 个字符，请分段输入。");

            // The nonnumeric prefix is disjoint from all normal source/target cache keys.
            string key = "alternative-japanese:" + text.Length + ":" + text;
            lock (cacheLock)
            {
                CacheItem hit;
                if (cache.TryGetValue(key, out hit))
                    return new TranslationResult { Text = hit.Text, Provider = hit.Provider + " · 缓存", ElapsedMs = 0 };
            }

            Stopwatch timer = Stopwatch.StartNew();
            string translated;
            try
            {
                translated = await TranslateGoogleAsync(text, "zh-Hans", "ja", token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                token.ThrowIfCancellationRequested();
                throw new InvalidOperationException("第二候选翻译连接超时，请稍后重试。");
            }
            catch (HttpRequestException)
            {
                token.ThrowIfCancellationRequested();
                throw new InvalidOperationException("第二候选翻译暂时无法连接，请检查网络后重试。");
            }
            catch (InvalidOperationException)
            {
                token.ThrowIfCancellationRequested();
                throw new InvalidOperationException("第二候选翻译暂时不可用，请稍后重试。");
            }

            token.ThrowIfCancellationRequested();
            timer.Stop();
            const string provider = "Google（第二候选）";
            translated = TranslationPunctuation.Normalize(translated, "ja");
            lock (cacheLock)
            {
                if (!cache.ContainsKey(key))
                {
                    while (cache.Count >= CacheCapacity)
                        cache.Remove(cacheOrder.Dequeue());
                    cache.Add(key, new CacheItem { Text = translated, Provider = provider });
                    cacheOrder.Enqueue(key);
                }
            }
            return new TranslationResult { Text = translated, Provider = provider, ElapsedMs = timer.ElapsedMilliseconds };
        }

        private static void ValidateLanguage(string language, bool allowAuto)
        {
            if (language == "zh-Hans" || language == "en" || language == "ja" || (allowAuto && language == "auto")) return;
            throw new ArgumentException("请选择中文、英文或日文。");
        }

        private async Task<string> TranslateMicrosoftAsync(string text, string source, string target, CancellationToken token)
        {
            string from = source == "auto" ? "" : source;
            string url = "https://edge.microsoft.com/translate/translatetext?from=" + Uri.EscapeDataString(from) +
                "&to=" + Uri.EscapeDataString(target) + "&isEnterpriseClient=false";
            JavaScriptSerializer json = CreateSerializer();
            using (HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Post, url))
            {
                request.Content = new StringContent(json.Serialize(new string[] { text }), Encoding.UTF8, "application/json");
                string raw = await SendAsync(request, token).ConfigureAwait(false);
                object decoded = Decode(json, raw);
                object first = First(decoded);
                IDictionary<string, object> item = first as IDictionary<string, object>;
                object values;
                if (item == null || !item.TryGetValue("translations", out values))
                    throw new InvalidOperationException("翻译服务返回了无法识别的结果。");
                IDictionary<string, object> translation = First(values) as IDictionary<string, object>;
                object value;
                if (translation == null || !translation.TryGetValue("text", out value) || !(value is string) || String.IsNullOrWhiteSpace((string)value))
                    throw new InvalidOperationException("翻译服务返回了空结果。");
                return (string)value;
            }
        }

        private async Task<string> TranslateFallbackAsync(string text, string source, string target, CancellationToken token)
        {
            try
            {
                return await TranslateGoogleAsync(text, source, target, token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                token.ThrowIfCancellationRequested();
                throw new InvalidOperationException("翻译连接超时，请检查网络后重试。");
            }
            catch (HttpRequestException)
            {
                token.ThrowIfCancellationRequested();
                throw new InvalidOperationException("翻译服务暂时无法连接，请检查网络后重试。");
            }
            catch (InvalidOperationException)
            {
                token.ThrowIfCancellationRequested();
                throw new InvalidOperationException("翻译服务暂时不可用，请稍后重试。");
            }
        }

        private async Task<string> TranslateGoogleAsync(string text, string source, string target, CancellationToken token)
        {
            string from = source == "zh-Hans" ? "zh-CN" : source;
            string to = target == "zh-Hans" ? "zh-CN" : target;
            string url = "https://translate.googleapis.com/translate_a/single?client=gtx&dt=t&dj=1&ie=UTF-8&sl=" +
                Uri.EscapeDataString(from) + "&tl=" + Uri.EscapeDataString(to) + "&q=" + Uri.EscapeDataString(text);
            using (HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Get, url))
            {
                string raw = await SendAsync(request, token).ConfigureAwait(false);
                IDictionary<string, object> root = Decode(CreateSerializer(), raw) as IDictionary<string, object>;
                object sentences;
                if (root == null || !root.TryGetValue("sentences", out sentences))
                    throw new InvalidOperationException("翻译服务返回了无法识别的结果。");
                IEnumerable sequence = sentences as IEnumerable;
                if (sequence == null || sentences is string)
                    throw new InvalidOperationException("翻译服务返回了无法识别的结果。");
                StringBuilder result = new StringBuilder();
                foreach (object segment in sequence)
                {
                    IDictionary<string, object> item = segment as IDictionary<string, object>;
                    object value;
                    if (item != null && item.TryGetValue("trans", out value) && value is string)
                        result.Append((string)value);
                }
                if (String.IsNullOrWhiteSpace(result.ToString()))
                    throw new InvalidOperationException("翻译服务返回了空结果。");
                return result.ToString();
            }
        }

        private async Task<string> SendAsync(HttpRequestMessage request, CancellationToken token)
        {
            using (CancellationTokenSource timeout = CancellationTokenSource.CreateLinkedTokenSource(token))
            {
                timeout.CancelAfter(TimeSpan.FromSeconds(RequestTimeoutSeconds));
                // ResponseContentRead ensures cancellation also covers a stalled response body.
                using (HttpResponseMessage response = await client.SendAsync(request, HttpCompletionOption.ResponseContentRead, timeout.Token).ConfigureAwait(false))
                {
                    token.ThrowIfCancellationRequested();
                    if (!response.IsSuccessStatusCode)
                        throw new HttpRequestException("翻译服务暂时无法完成请求。");
                    return await response.Content.ReadAsStringAsync().ConfigureAwait(false);
                }
            }
        }

        private static JavaScriptSerializer CreateSerializer()
        {
            return new JavaScriptSerializer { MaxJsonLength = 1024 * 1024, RecursionLimit = 32 };
        }

        private static object Decode(JavaScriptSerializer json, string raw)
        {
            try { return json.DeserializeObject(raw); }
            catch (ArgumentException) { throw new InvalidOperationException("翻译服务返回了无法识别的结果。"); }
        }

        private static object First(object value)
        {
            IEnumerable items = value as IEnumerable;
            if (items == null || value is string || value is IDictionary) return null;
            foreach (object item in items) return item;
            return null;
        }

        public void Dispose()
        {
            if (disposed) return;
            disposed = true;
            client.Dispose();
            lock (cacheLock)
            {
                cache.Clear();
                cacheOrder.Clear();
            }
        }
    }
}

using System;
using System.ComponentModel;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Interop;

namespace Yuqiao
{
    // Launch only. Windows owns recognition, microphone access and its UI.
    // No audio capture, recognition engine, recording file or cloud key here.
    public static class WindowsVoiceInput
    {
        [StructLayout(LayoutKind.Sequential)] internal struct INPUT { public uint type; public InputUnion data; }
        [StructLayout(LayoutKind.Explicit)] internal struct InputUnion
        {
            [FieldOffset(0)] public KEYBDINPUT keyboard;
            [FieldOffset(0)] public MOUSEINPUT mouse;
        }
        [StructLayout(LayoutKind.Sequential)] internal struct KEYBDINPUT { public ushort key, scan; public uint flags, time; public UIntPtr extra; }
        [StructLayout(LayoutKind.Sequential)] internal struct MOUSEINPUT { public int x, y; public uint data, flags, time; public UIntPtr extra; }
        [DllImport("user32.dll", SetLastError=true)] static extern uint SendInput(uint count, INPUT[] inputs, int size);
        [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
        [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr window, out uint process);
        [DllImport("user32.dll")] static extern short GetAsyncKeyState(int key);

        internal static INPUT[] Shortcut()
        { return new[] { Key(0x5B,false),Key(0x48,false),Key(0x48,true),Key(0x5B,true) }; }
        static INPUT Key(ushort key, bool up)
        { return new INPUT { type=1, data=new InputUnion { keyboard=new KEYBDINPUT { key=key,flags=up?2u:0u } } }; }
        public static void Request(TextBox editor)
        {
            if(editor==null||editor.IsReadOnly||!editor.IsEnabled||!editor.IsVisible)throw new InvalidOperationException("中文输入框当前不可用。");
            Window owner=Window.GetWindow(editor);
            if(owner==null||!owner.IsVisible||owner.WindowState==WindowState.Minimized)throw new InvalidOperationException("请先显示中文输入框。");
            if((GetAsyncKeyState(0x11)&0x8000)!=0||(GetAsyncKeyState(0x12)&0x8000)!=0||(GetAsyncKeyState(0x10)&0x8000)!=0)
                throw new InvalidOperationException("请先松开 Ctrl、Alt 和 Shift，再点击语音输入。");
            owner.Activate(); editor.Focus(); Keyboard.Focus(editor);
            editor.Select(editor.Text.Length,0);
            IntPtr handle=new WindowInteropHelper(owner).Handle;
            if(GetForegroundWindow()!=handle||!editor.IsKeyboardFocused)throw new InvalidOperationException("光标未能进入中文输入框，请再次点击语音输入。");
            INPUT[] inputs=Shortcut();
            uint sent=SendInput((uint)inputs.Length,inputs,Marshal.SizeOf(typeof(INPUT)));
            if(sent!=inputs.Length)
            {
                int error=Marshal.GetLastWin32Error();
                INPUT[] release={Key(0x48,true),Key(0x5B,true)};
                SendInput((uint)release.Length,release,Marshal.SizeOf(typeof(INPUT)));
                throw new Win32Exception(error,"系统未接受语音输入快捷键。");
            }
        }
        public static bool IsSystemInputForeground()
        {
            try
            {
                uint process; GetWindowThreadProcessId(GetForegroundWindow(),out process);
                using(Process p=Process.GetProcessById((int)process))
                    return String.Equals(p.ProcessName,"TextInputHost",StringComparison.OrdinalIgnoreCase)
                        ||String.Equals(p.ProcessName,"InputApp",StringComparison.OrdinalIgnoreCase);
            }catch(Exception){return false;}
        }
        public static void End(TextBox editor)
        {
            if(editor==null||!editor.IsVisible)throw new InvalidOperationException("请先显示中文输入框。");
            Window owner=Window.GetWindow(editor);
            if(owner==null)throw new InvalidOperationException("中文输入窗口不可用。");
            IntPtr handle=new WindowInteropHelper(owner).Handle;
            if(GetForegroundWindow()!=handle&&!IsSystemInputForeground())throw new InvalidOperationException("请在中文输入框结束听写。");
            owner.Activate();editor.Focus();Keyboard.Focus(editor);
            if(GetForegroundWindow()!=handle||!editor.IsKeyboardFocused)throw new InvalidOperationException("光标未在中文输入框，未切换到 Claude。");
            INPUT[] inputs={Key(0x1B,false),Key(0x1B,true)};
            if(SendInput((uint)inputs.Length,inputs,Marshal.SizeOf(typeof(INPUT)))!=inputs.Length)throw new InvalidOperationException("系统未接受结束听写操作。");
        }
    }
}

